from __future__ import annotations

from knowledge_layer_core.data_model_schema import (
    CORE_DATA_TABLES,
    CORE_TABLE_DDL,
    CORE_VIEW_DDL,
)

SCHEMA_VERSION = 'workspace_data_model/v16'

WORKSPACE_EXTENSION_TABLE_DDL = 'CREATE TABLE data_model_correspondence_observation (\n    observation_id VARCHAR PRIMARY KEY,\n    observation_kind VARCHAR NOT NULL,\n    normalized_value VARCHAR NOT NULL,\n    left_repo_id VARCHAR NOT NULL,\n    left_occurrence_id VARCHAR NOT NULL,\n    right_repo_id VARCHAR NOT NULL,\n    right_occurrence_id VARCHAR NOT NULL,\n    basis_json JSON NOT NULL\n);\n\nCREATE TABLE type_reference_resolution_candidate (\n    resolution_candidate_id VARCHAR PRIMARY KEY,\n    source_observation_occurrence_id VARCHAR NOT NULL,\n    source_repo_id VARCHAR NOT NULL,\n    owner_fqcn VARCHAR,\n    referenced_type VARCHAR,\n    observed_resolved_fqcn VARCHAR,\n    candidate_fqcn VARCHAR NOT NULL,\n    target_repo_id VARCHAR NOT NULL,\n    target_java_type_occurrence_id VARCHAR NOT NULL,\n    match_scope VARCHAR NOT NULL,\n    match_basis VARCHAR NOT NULL,\n    payload_json JSON NOT NULL\n);\n\nCREATE TABLE model_relationship_observation (\n    relationship_id VARCHAR PRIMARY KEY,\n    source_repo_id VARCHAR NOT NULL,\n    source_object_fqcn VARCHAR NOT NULL,\n    source_java_type_occurrence_id VARCHAR,\n    source_key_observation_ids_json JSON NOT NULL,\n    source_field_occurrence_id VARCHAR NOT NULL,\n    source_field_name VARCHAR NOT NULL,\n    source_field_owner_fqcn VARCHAR NOT NULL,\n    source_field_inherited BOOLEAN NOT NULL,\n    source_field_inheritance_depth BIGINT NOT NULL,\n    target_repo_id VARCHAR,\n    target_type_fqcn VARCHAR NOT NULL,\n    target_java_type_occurrence_id VARCHAR,\n    target_key_observation_ids_json JSON NOT NULL,\n    relation_kind VARCHAR NOT NULL,\n    cardinality VARCHAR NOT NULL,\n    field_container_kind VARCHAR,\n    converter_operation VARCHAR,\n    converter_owner_fqcns_json JSON NOT NULL,\n    converter_operation_observation_ids_json JSON NOT NULL,\n    observation_basis_json JSON NOT NULL,\n    payload_json JSON NOT NULL\n);\n\nCREATE TABLE model_relationship_key_expression (\n    key_expression_id VARCHAR PRIMARY KEY,\n    relationship_id VARCHAR NOT NULL,\n    endpoint_role VARCHAR NOT NULL,\n    expression_text VARCHAR NOT NULL,\n    source_repo_ids_json JSON NOT NULL,\n    converter_owner_fqcns_json JSON NOT NULL,\n    owner_methods_json JSON NOT NULL,\n    source_observation_occurrence_ids_json JSON NOT NULL,\n    input_symbols_json JSON NOT NULL,\n    payload_json JSON NOT NULL\n);\n\nCREATE TABLE model_relationship_storage_key_derivation (\n    key_lineage_id VARCHAR PRIMARY KEY,\n    relationship_id VARCHAR NOT NULL,\n    lineage_repo_id VARCHAR NOT NULL,\n    source_observation_occurrence_id VARCHAR NOT NULL,\n    source_alias VARCHAR NOT NULL,\n    relationship_field VARCHAR NOT NULL,\n    target_alias VARCHAR NOT NULL,\n    target_storage_key_field VARCHAR,\n    reference_operation VARCHAR,\n    source_operation VARCHAR,\n    collection_helper_operation VARCHAR,\n    target_key_operation VARCHAR,\n    source_key_expression VARCHAR,\n    target_key_expression_template VARCHAR,\n    composed_target_key_expression VARCHAR,\n    source_key_input_symbols_json JSON NOT NULL,\n    target_key_template_input_symbols_json JSON NOT NULL,\n    composed_target_key_input_symbols_json JSON NOT NULL,\n    source_key_parameter_bindings_json JSON NOT NULL,\n    source_key_passed_into_target_key BOOLEAN NOT NULL,\n    binding_path_json JSON NOT NULL,\n    target_path_depth BIGINT,\n    observation_basis VARCHAR NOT NULL,\n    payload_json JSON NOT NULL\n);\n\nCREATE TABLE model_relationship_reference_value_key_correspondence (\n    correspondence_id VARCHAR PRIMARY KEY,\n    relationship_id VARCHAR NOT NULL,\n    source_repo_id VARCHAR NOT NULL,\n    reference_value_observation_occurrence_id VARCHAR NOT NULL,\n    source_alias VARCHAR NOT NULL,\n    relationship_field VARCHAR NOT NULL,\n    target_alias VARCHAR NOT NULL,\n    reference_operation VARCHAR,\n    source_operation VARCHAR,\n    value_converter_operation VARCHAR,\n    reference_value_expression VARCHAR,\n    return_expression_template VARCHAR,\n    composed_reference_value_expression VARCHAR NOT NULL,\n    target_key_observation_occurrence_id VARCHAR NOT NULL,\n    target_key_owner_fqcn VARCHAR NOT NULL,\n    target_key_operation VARCHAR NOT NULL,\n    target_key_expression VARCHAR NOT NULL,\n    target_key_fields_json JSON NOT NULL,\n    reference_value_signature_json JSON NOT NULL,\n    target_key_signature_json JSON NOT NULL,\n    value_converter_parameter_bindings_json JSON NOT NULL,\n    binding_path_json JSON NOT NULL,\n    match_basis VARCHAR NOT NULL,\n    observation_basis VARCHAR NOT NULL,\n    payload_json JSON NOT NULL\n);\n\nCREATE TABLE model_relationship_storage_reference (\n    storage_reference_id VARCHAR PRIMARY KEY,\n    relationship_id VARCHAR NOT NULL,\n    source_repo_id VARCHAR NOT NULL,\n    source_observation_occurrence_id VARCHAR NOT NULL,\n    source_alias VARCHAR NOT NULL,\n    relationship_field VARCHAR NOT NULL,\n    reference_operation VARCHAR,\n    source_operation VARCHAR,\n    reference_value_expression VARCHAR,\n    reference_value_binding_resolution VARCHAR,\n    target_converter_operation VARCHAR,\n    target_storage_record_observation_local_id VARCHAR,\n    target_storage_record_observation_occurrence_id VARCHAR,\n    target_alias VARCHAR NOT NULL,\n    target_storage_key_field VARCHAR NOT NULL,\n    target_storage_key_expression VARCHAR NOT NULL,\n    target_storage_key_local_variable VARCHAR,\n    target_storage_key_input_symbols_json JSON NOT NULL,\n    target_storage_key_expression_tree_json JSON NOT NULL,\n    value_origin VARCHAR NOT NULL,\n    type_source VARCHAR,\n    key_source VARCHAR,\n    physical_encoding VARCHAR NOT NULL,\n    binding_path_json JSON NOT NULL,\n    observation_basis VARCHAR NOT NULL,\n    payload_json JSON NOT NULL\n);\n\nCREATE TABLE model_relationship_polymorphic_target (\n    polymorphic_target_id VARCHAR PRIMARY KEY,\n    relationship_id VARCHAR NOT NULL,\n    target_type_fqcn VARCHAR NOT NULL,\n    target_java_type_occurrence_id VARCHAR,\n    source_repo_ids_json JSON NOT NULL,\n    source_observation_occurrence_ids_json JSON NOT NULL,\n    payload_json JSON NOT NULL\n);\n\nCREATE TABLE artifact_dependency_correspondence_observation (\n    observation_id VARCHAR PRIMARY KEY,\n    normalized_coordinate VARCHAR NOT NULL,\n    group_id VARCHAR NOT NULL,\n    artifact_id VARCHAR NOT NULL,\n    left_repo_id VARCHAR NOT NULL,\n    left_source_observation_occurrence_id VARCHAR NOT NULL,\n    right_repo_id VARCHAR NOT NULL,\n    right_source_observation_occurrence_id VARCHAR NOT NULL,\n    basis_json JSON NOT NULL\n);'

WORKSPACE_EXTENSION_VIEW_DDL = "CREATE VIEW v_tsa_annotations AS\nSELECT c.*,\n       json_extract_string(s.payload_json, '$.properties.tsa_observation_kind') AS tsa_observation_kind,\n       json_extract_string(s.payload_json, '$.properties.source_observation_id') AS source_observation_local_id,\n       s.arguments_json\nFROM v_source_observation_compact c\nJOIN source_observation s USING(source_observation_occurrence_id)\nWHERE c.fact_type='tsa_annotation_observation';\n\nCREATE VIEW v_tsa_converter_configurations AS\nSELECT c.*,\n       json_extract_string(s.payload_json, '$.properties.tsa_observation_kind') AS tsa_observation_kind,\n       json_extract_string(s.payload_json, '$.properties.configured_class_name') AS configured_class_name,\n       json_extract_string(s.payload_json, '$.properties.source_observation_id') AS source_observation_local_id\nFROM v_source_observation_compact c\nJOIN source_observation s USING(source_observation_occurrence_id)\nWHERE c.fact_type='tsa_converter_configuration_observation';\n\nCREATE VIEW v_tsa_configuration_directives AS\nSELECT c.*,\n       json_extract_string(s.payload_json, '$.properties.tsa_observation_kind') AS tsa_observation_kind,\n       json_extract_string(s.payload_json, '$.properties.value') AS directive_value,\n       json_extract_string(s.payload_json, '$.properties.source_observation_id') AS source_observation_local_id\nFROM v_source_observation_compact c\nJOIN source_observation s USING(source_observation_occurrence_id)\nWHERE c.fact_type='tsa_configuration_directive_observation';\n\nCREATE VIEW v_model_configuration_directives AS\nWITH normalized AS (\n    SELECT d.source_observation_occurrence_id AS directive_observation_id,\n           d.repo_id AS directive_repo_id,\n           d.source_path,\n           d.line_start,\n           d.line_end,\n           d.configuration_path,\n           d.tsa_observation_kind AS directive_kind,\n           d.directive_value,\n           CASE\n             WHEN d.tsa_observation_kind='excluded_type' THEN 'qualified_type'\n             WHEN d.tsa_observation_kind='excluded_field' AND strpos(d.directive_value, ':')=0 THEN 'global_field_name'\n             WHEN d.tsa_observation_kind IN (\n                    'excluded_field','custom_field_mapping_endpoint','custom_primitive_converter_endpoint'\n                  ) THEN 'qualified_field'\n             ELSE 'unclassified'\n           END AS directive_scope_kind,\n           CASE\n             WHEN strpos(d.directive_value, ':')>0\n               THEN left(d.directive_value, strpos(d.directive_value, ':')-1)\n             WHEN d.tsa_observation_kind='excluded_type'\n               THEN d.directive_value\n             ELSE NULL\n           END AS object_fqcn,\n           CASE\n             WHEN strpos(d.directive_value, ':')>0\n               THEN substr(d.directive_value, strpos(d.directive_value, ':')+1)\n             WHEN d.tsa_observation_kind='excluded_field'\n               THEN d.directive_value\n             ELSE NULL\n           END AS field_name,\n           CASE\n             WHEN strpos(d.configuration_path, '.')>0\n               THEN regexp_replace(d.configuration_path, '[.][^.]+$', '')\n             ELSE d.configuration_path\n           END AS mapping_parent_path\n    FROM v_tsa_configuration_directives d\n), sibling_values AS (\n    SELECT repo_id,\n           source_path,\n           parent_path,\n           to_json(list(source_observation_occurrence_id ORDER BY configuration_path, source_observation_occurrence_id))\n             AS sibling_configuration_entry_ids_json,\n           max(CASE WHEN ends_with(configuration_path, '.targetType')\n                    THEN json_extract_string(scalar_value_json, '$') END) AS configured_target_type,\n           max(CASE WHEN ends_with(configuration_path, '.targetCollectionType')\n                    THEN json_extract_string(scalar_value_json, '$') END) AS configured_target_collection_type,\n           max(CASE WHEN ends_with(configuration_path, '.instantiator')\n                    THEN json_extract_string(scalar_value_json, '$') END) AS converter_instantiator\n    FROM v_configuration_entries\n    WHERE parent_path IS NOT NULL\n      AND (\n        configuration_path LIKE 'customFields[%].%'\n        OR configuration_path LIKE '%.customPrimitiveConvertors[%].%'\n      )\n    GROUP BY repo_id, source_path, parent_path\n)\nSELECT n.directive_observation_id,\n       n.directive_repo_id,\n       n.source_path,\n       n.line_start,\n       n.line_end,\n       n.configuration_path,\n       n.directive_kind,\n       n.directive_value,\n       n.directive_scope_kind,\n       n.object_fqcn,\n       n.field_name,\n       n.mapping_parent_path,\n       s.configured_target_type,\n       s.configured_target_collection_type,\n       s.converter_instantiator,\n       coalesce(s.sibling_configuration_entry_ids_json, json('[]')) AS sibling_configuration_entry_ids_json\nFROM normalized n\nLEFT JOIN sibling_values s\n  ON s.repo_id=n.directive_repo_id\n AND s.source_path=n.source_path\n AND s.parent_path=n.mapping_parent_path;\n\nCREATE VIEW v_model_configuration_directive_matches AS\nSELECT d.directive_observation_id,\n       d.directive_repo_id,\n       d.directive_kind,\n       d.directive_value,\n       d.directive_scope_kind,\n       d.object_fqcn,\n       d.field_name,\n       d.configuration_path,\n       d.configured_target_type,\n       d.configured_target_collection_type,\n       d.converter_instantiator,\n       d.sibling_configuration_entry_ids_json,\n       'model_object' AS match_kind,\n       'exact_object_fqcn' AS match_basis,\n       k.repo_id AS matched_repo_id,\n       k.object_fqcn AS matched_object_fqcn,\n       NULL::VARCHAR AS matched_field_occurrence_id,\n       NULL::VARCHAR AS matched_field_name\nFROM v_model_configuration_directives d\nJOIN model_object_key_observation k\n  ON d.directive_kind='excluded_type'\n AND k.object_fqcn=d.object_fqcn\nUNION ALL\nSELECT d.directive_observation_id,\n       d.directive_repo_id,\n       d.directive_kind,\n       d.directive_value,\n       d.directive_scope_kind,\n       d.object_fqcn,\n       d.field_name,\n       d.configuration_path,\n       d.configured_target_type,\n       d.configured_target_collection_type,\n       d.converter_instantiator,\n       d.sibling_configuration_entry_ids_json,\n       'model_field' AS match_kind,\n       CASE\n         WHEN d.directive_scope_kind='global_field_name' THEN 'global_field_name'\n         WHEN d.object_fqcn=f.effective_owner_fqcn THEN 'effective_owner_fqcn_and_field_name'\n         ELSE 'declaration_owner_fqcn_and_field_name'\n       END AS match_basis,\n       f.repo_id AS matched_repo_id,\n       f.effective_owner_fqcn AS matched_object_fqcn,\n       f.effective_field_occurrence_id AS matched_field_occurrence_id,\n       f.field_name AS matched_field_name\nFROM v_model_configuration_directives d\nJOIN effective_entity_field f\n  ON d.directive_kind IN (\n       'excluded_field','custom_field_mapping_endpoint','custom_primitive_converter_endpoint'\n     )\n AND d.field_name=f.field_name\n AND (\n      d.directive_scope_kind='global_field_name'\n      OR d.object_fqcn=f.effective_owner_fqcn\n      OR d.object_fqcn=f.declaration_owner_fqcn\n );\n\nCREATE VIEW v_model_object_configuration_observations AS\nSELECT k.*,\n       EXISTS(\n         SELECT 1 FROM v_model_configuration_directives d\n         WHERE d.directive_kind='excluded_type' AND d.object_fqcn=k.object_fqcn\n       ) AS configuration_type_exclusion_observed,\n       coalesce((\n         SELECT to_json(list(d.directive_observation_id ORDER BY d.directive_observation_id))\n         FROM v_model_configuration_directives d\n         WHERE d.directive_kind='excluded_type' AND d.object_fqcn=k.object_fqcn\n       ), json('[]')) AS configuration_type_exclusion_directive_ids_json,\n       coalesce((\n         SELECT to_json(list(d.configuration_path ORDER BY d.configuration_path, d.directive_observation_id))\n         FROM v_model_configuration_directives d\n         WHERE d.directive_kind='excluded_type' AND d.object_fqcn=k.object_fqcn\n       ), json('[]')) AS configuration_type_exclusion_paths_json\nFROM model_object_key_observation k;\n\nCREATE VIEW v_tsa_reference_operations AS\nSELECT c.*,\n       json_extract_string(s.payload_json, '$.properties.tsa_observation_kind') AS tsa_observation_kind,\n       json_extract(s.payload_json, '$.properties.argument_expressions') AS argument_expressions_json,\n       json_extract(s.payload_json, '$.properties.argument_input_symbols') AS argument_input_symbols_json,\n       json_extract(s.payload_json, '$.properties.argument_expression_trees') AS argument_expression_trees_json\nFROM v_source_observation_compact c\nJOIN source_observation s USING(source_observation_occurrence_id)\nWHERE c.fact_type='tsa_reference_operation_observation';\n\nCREATE VIEW v_tsa_key_expressions AS\nSELECT c.*,\n       json_extract_string(s.payload_json, '$.properties.tsa_observation_kind') AS tsa_observation_kind,\n       json_extract_string(s.payload_json, '$.properties.key_expression') AS key_expression,\n       json_extract(s.payload_json, '$.properties.input_symbols') AS key_input_symbols_json,\n       json_extract(s.payload_json, '$.properties.expression_tree') AS key_expression_tree_json\nFROM v_source_observation_compact c\nJOIN source_observation s USING(source_observation_occurrence_id)\nWHERE c.fact_type='tsa_key_expression_observation';\n\nCREATE VIEW v_tsa_storage_key_derivations AS\nSELECT c.*,\n       json_extract_string(s.payload_json, '$.properties.tsa_observation_kind') AS tsa_observation_kind,\n       json_extract_string(s.payload_json, '$.properties.source_alias') AS source_alias,\n       json_extract_string(s.payload_json, '$.properties.relationship_field') AS relationship_field,\n       json_extract_string(s.payload_json, '$.properties.target_alias') AS target_alias,\n       json_extract_string(s.payload_json, '$.properties.target_storage_key_field') AS target_storage_key_field,\n       json_extract_string(s.payload_json, '$.properties.reference_operation') AS reference_operation,\n       json_extract_string(s.payload_json, '$.properties.source_operation') AS source_operation,\n       json_extract_string(s.payload_json, '$.properties.collection_helper_operation') AS collection_helper_operation,\n       json_extract_string(s.payload_json, '$.properties.target_key_operation') AS target_key_operation,\n       json_extract_string(s.payload_json, '$.properties.source_key_expression') AS source_key_expression,\n       json_extract_string(s.payload_json, '$.properties.target_key_expression_template') AS target_key_expression_template,\n       json_extract_string(s.payload_json, '$.properties.composed_target_key_expression') AS composed_target_key_expression,\n       json_extract(s.payload_json, '$.properties.source_key_input_symbols') AS source_key_input_symbols_json,\n       json_extract(s.payload_json, '$.properties.target_key_template_input_symbols') AS target_key_template_input_symbols_json,\n       json_extract(s.payload_json, '$.properties.composed_target_key_input_symbols') AS composed_target_key_input_symbols_json,\n       json_extract(s.payload_json, '$.properties.source_key_parameter_bindings') AS source_key_parameter_bindings_json,\n       coalesce(try_cast(json_extract_string(s.payload_json, '$.properties.source_key_passed_into_target_key') AS BOOLEAN), false) AS source_key_passed_into_target_key,\n       json_extract(s.payload_json, '$.properties.binding_path') AS binding_path_json,\n       try_cast(json_extract_string(s.payload_json, '$.properties.target_path_depth') AS BIGINT) AS target_path_depth,\n       json_extract_string(s.payload_json, '$.properties.observation_policy') AS observation_policy\nFROM v_source_observation_compact c\nJOIN source_observation s USING(source_observation_occurrence_id)\nWHERE c.fact_type='tsa_storage_key_lineage_observation';\n\nCREATE VIEW v_tsa_reference_value_derivations AS\nSELECT c.*,\n       json_extract_string(s.payload_json, '$.properties.tsa_observation_kind') AS tsa_observation_kind,\n       json_extract_string(s.payload_json, '$.properties.source_alias') AS source_alias,\n       json_extract_string(s.payload_json, '$.properties.relationship_field') AS relationship_field,\n       json_extract_string(s.payload_json, '$.properties.reference_operation') AS reference_operation,\n       json_extract_string(s.payload_json, '$.properties.source_operation') AS source_operation,\n       json_extract_string(s.payload_json, '$.properties.value_converter_operation') AS value_converter_operation,\n       json_extract_string(s.payload_json, '$.properties.reference_value_expression') AS reference_value_expression,\n       json_extract_string(s.payload_json, '$.properties.return_expression_template') AS return_expression_template,\n       json_extract_string(s.payload_json, '$.properties.composed_reference_value_expression') AS composed_reference_value_expression,\n       json_extract(s.payload_json, '$.properties.composed_reference_value_expression_tree') AS composed_reference_value_expression_tree_json,\n       json_extract(s.payload_json, '$.properties.composed_reference_value_input_symbols') AS composed_reference_value_input_symbols_json,\n       json_extract(s.payload_json, '$.properties.value_converter_parameter_bindings') AS value_converter_parameter_bindings_json,\n       json_extract(s.payload_json, '$.properties.binding_path') AS binding_path_json,\n       json_extract_string(s.payload_json, '$.properties.observation_policy') AS observation_policy\nFROM v_source_observation_compact c\nJOIN source_observation s USING(source_observation_occurrence_id)\nWHERE c.fact_type='tsa_reference_value_derivation_observation';\n\nCREATE VIEW v_model_object_fields AS\nSELECT k.key_observation_id,\n       k.repo_id,\n       k.object_fqcn,\n       k.java_type_occurrence_id,\n       k.annotation_name,\n       f.effective_field_occurrence_id,\n       f.field_name,\n       f.declared_type,\n       f.effective_type,\n       f.declaration_owner_fqcn,\n       f.inherited,\n       f.inheritance_depth,\n       f.inheritance_path_json,\n       f.container_kind,\n       f.element_type,\n       json_extract_string(f.payload_json, '$.display_name') AS display_name,\n       json_extract_string(f.payload_json, '$.description') AS description,\n       f.model_exclusion_observed,\n       f.model_exclusion_annotations_json,\n       f.association_origin AS field_projection_basis,\n       m.key_member_id,\n       m.position AS key_position,\n       m.role_name AS key_role_name,\n       m.field_resolution_kind AS key_field_resolution_kind,\n       m.inheritance_depth AS key_field_inheritance_depth,\n       EXISTS(\n         SELECT 1 FROM v_model_configuration_directives d\n         WHERE d.directive_kind='excluded_field'\n           AND d.field_name=f.field_name\n           AND (\n             d.directive_scope_kind='global_field_name'\n             OR d.object_fqcn=f.effective_owner_fqcn\n             OR d.object_fqcn=f.declaration_owner_fqcn\n           )\n       ) AS configuration_field_exclusion_observed,\n       coalesce((\n         SELECT to_json(list(d.directive_observation_id ORDER BY d.directive_observation_id))\n         FROM v_model_configuration_directives d\n         WHERE d.directive_kind='excluded_field'\n           AND d.field_name=f.field_name\n           AND (\n             d.directive_scope_kind='global_field_name'\n             OR d.object_fqcn=f.effective_owner_fqcn\n             OR d.object_fqcn=f.declaration_owner_fqcn\n           )\n       ), json('[]')) AS configuration_exclusion_directive_ids_json,\n       EXISTS(\n         SELECT 1 FROM v_model_configuration_directives d\n         WHERE d.directive_kind='custom_field_mapping_endpoint'\n           AND d.field_name=f.field_name\n           AND (d.object_fqcn=f.effective_owner_fqcn OR d.object_fqcn=f.declaration_owner_fqcn)\n       ) AS custom_field_mapping_observed,\n       coalesce((\n         SELECT to_json(list(d.directive_observation_id ORDER BY d.directive_observation_id))\n         FROM v_model_configuration_directives d\n         WHERE d.directive_kind='custom_field_mapping_endpoint'\n           AND d.field_name=f.field_name\n           AND (d.object_fqcn=f.effective_owner_fqcn OR d.object_fqcn=f.declaration_owner_fqcn)\n       ), json('[]')) AS custom_field_mapping_directive_ids_json,\n       coalesce((\n         SELECT to_json(list(DISTINCT d.configured_target_type ORDER BY d.configured_target_type))\n         FROM v_model_configuration_directives d\n         WHERE d.directive_kind='custom_field_mapping_endpoint'\n           AND d.field_name=f.field_name\n           AND (d.object_fqcn=f.effective_owner_fqcn OR d.object_fqcn=f.declaration_owner_fqcn)\n           AND d.configured_target_type IS NOT NULL\n       ), json('[]')) AS configured_target_types_json,\n       coalesce((\n         SELECT to_json(list(DISTINCT d.configured_target_collection_type ORDER BY d.configured_target_collection_type))\n         FROM v_model_configuration_directives d\n         WHERE d.directive_kind='custom_field_mapping_endpoint'\n           AND d.field_name=f.field_name\n           AND (d.object_fqcn=f.effective_owner_fqcn OR d.object_fqcn=f.declaration_owner_fqcn)\n           AND d.configured_target_collection_type IS NOT NULL\n       ), json('[]')) AS configured_target_collection_types_json,\n       EXISTS(\n         SELECT 1 FROM v_model_configuration_directives d\n         WHERE d.directive_kind='custom_primitive_converter_endpoint'\n           AND d.field_name=f.field_name\n           AND (d.object_fqcn=f.effective_owner_fqcn OR d.object_fqcn=f.declaration_owner_fqcn)\n       ) AS custom_primitive_converter_observed,\n       coalesce((\n         SELECT to_json(list(d.directive_observation_id ORDER BY d.directive_observation_id))\n         FROM v_model_configuration_directives d\n         WHERE d.directive_kind='custom_primitive_converter_endpoint'\n           AND d.field_name=f.field_name\n           AND (d.object_fqcn=f.effective_owner_fqcn OR d.object_fqcn=f.declaration_owner_fqcn)\n       ), json('[]')) AS custom_primitive_converter_directive_ids_json,\n       coalesce((\n         SELECT to_json(list(DISTINCT d.converter_instantiator ORDER BY d.converter_instantiator))\n         FROM v_model_configuration_directives d\n         WHERE d.directive_kind='custom_primitive_converter_endpoint'\n           AND d.field_name=f.field_name\n           AND (d.object_fqcn=f.effective_owner_fqcn OR d.object_fqcn=f.declaration_owner_fqcn)\n           AND d.converter_instantiator IS NOT NULL\n       ), json('[]')) AS custom_converter_instantiators_json\nFROM model_object_key_observation k\nJOIN effective_entity_field f\n  ON f.repo_id=k.repo_id AND f.effective_owner_fqcn=k.object_fqcn\nLEFT JOIN model_object_key_member m\n  ON m.key_observation_id=k.key_observation_id\n AND (m.field_occurrence_id=f.effective_field_occurrence_id OR\n      (m.field_name=f.field_name AND m.field_owner_fqcn=f.declaration_owner_fqcn));\n\nCREATE VIEW v_model_relationship_storage_key_derivation AS\nSELECT l.*,\n       r.source_repo_id,\n       r.source_object_fqcn,\n       r.source_field_name,\n       r.target_repo_id,\n       r.target_type_fqcn,\n       r.relation_kind,\n       r.cardinality\nFROM model_relationship_storage_key_derivation l\nJOIN model_relationship_observation r USING(relationship_id);\n\nCREATE VIEW v_model_relationship_reference_value_key_correspondence AS\nSELECT c.*,\n       r.source_repo_id AS relationship_source_repo_id,\n       r.source_object_fqcn,\n       r.source_field_name,\n       r.target_repo_id,\n       r.target_type_fqcn,\n       r.relation_kind,\n       r.cardinality\nFROM model_relationship_reference_value_key_correspondence c\nJOIN model_relationship_observation r USING(relationship_id);\n\nCREATE VIEW v_model_relationship_key_expression_bindings AS\nSELECT e.key_expression_id,\n       e.relationship_id,\n       e.endpoint_role,\n       e.expression_text,\n       e.source_repo_ids_json,\n       e.converter_owner_fqcns_json,\n       e.owner_methods_json,\n       e.source_observation_occurrence_ids_json,\n       e.input_symbols_json,\n       json_extract_string(binding.value, '$.binding_kind') AS binding_kind,\n       json_extract_string(binding.value, '$.reference_operation_observation_id') AS reference_operation_observation_id,\n       json_extract_string(binding.value, '$.source_object_fqcn') AS source_object_fqcn,\n       json_extract_string(binding.value, '$.source_field_name') AS source_field_name,\n       json_extract_string(binding.value, '$.target_type_fqcn') AS target_type_fqcn,\n       json_extract(binding.value, '$.endpoint_key_observation_ids') AS endpoint_key_observation_ids_json,\n       json_extract_string(binding.value, '$.nested_converter_method') AS nested_converter_method,\n       binding.value AS binding_payload_json\nFROM model_relationship_key_expression e,\n     json_each(coalesce(json_extract(e.payload_json, '$.observations'), json('[]'))) binding;\n\nCREATE VIEW v_model_relationship_configuration_observations AS\nSELECT r.*,\n       EXISTS(\n         SELECT 1 FROM v_model_configuration_directives d\n         WHERE d.directive_kind='excluded_field'\n           AND d.field_name=r.source_field_name\n           AND (\n             d.directive_scope_kind='global_field_name'\n             OR d.object_fqcn=r.source_object_fqcn\n             OR d.object_fqcn=r.source_field_owner_fqcn\n           )\n       ) AS source_field_configuration_exclusion_observed,\n       coalesce((\n         SELECT to_json(list(d.directive_observation_id ORDER BY d.directive_observation_id))\n         FROM v_model_configuration_directives d\n         WHERE d.directive_kind='excluded_field'\n           AND d.field_name=r.source_field_name\n           AND (\n             d.directive_scope_kind='global_field_name'\n             OR d.object_fqcn=r.source_object_fqcn\n             OR d.object_fqcn=r.source_field_owner_fqcn\n           )\n       ), json('[]')) AS source_field_configuration_exclusion_directive_ids_json,\n       EXISTS(\n         SELECT 1 FROM v_model_configuration_directives d\n         WHERE d.directive_kind='excluded_type' AND d.object_fqcn=r.target_type_fqcn\n       ) AS target_type_configuration_exclusion_observed,\n       coalesce((\n         SELECT to_json(list(d.directive_observation_id ORDER BY d.directive_observation_id))\n         FROM v_model_configuration_directives d\n         WHERE d.directive_kind='excluded_type' AND d.object_fqcn=r.target_type_fqcn\n       ), json('[]')) AS target_type_configuration_exclusion_directive_ids_json\nFROM model_relationship_observation r;\n\nCREATE VIEW v_model_relationship_join_evidence AS\nSELECT r.*,\n       json_array_length(r.source_key_observation_ids_json) AS source_key_observation_count,\n       json_array_length(r.target_key_observation_ids_json) AS target_key_observation_count,\n       (SELECT count(*) FROM model_relationship_key_expression e\n        WHERE e.relationship_id=r.relationship_id) AS key_expression_count,\n       (SELECT count(*) FROM model_relationship_key_expression e\n        WHERE e.relationship_id=r.relationship_id AND e.endpoint_role='source') AS source_key_expression_count,\n       (SELECT count(*) FROM model_relationship_key_expression e\n        WHERE e.relationship_id=r.relationship_id AND e.endpoint_role='target') AS target_key_expression_count,\n       (SELECT count(*) FROM v_model_relationship_key_expression_bindings b\n        WHERE b.relationship_id=r.relationship_id) AS key_expression_binding_count,\n       (SELECT count(DISTINCT b.reference_operation_observation_id)\n        FROM v_model_relationship_key_expression_bindings b\n        WHERE b.relationship_id=r.relationship_id\n          AND b.reference_operation_observation_id IS NOT NULL\n          AND b.reference_operation_observation_id <> '') AS bound_reference_operation_count,\n       (SELECT count(*) FROM model_relationship_polymorphic_target p\n        WHERE p.relationship_id=r.relationship_id) AS polymorphic_target_count,\n       (SELECT count(*) FROM model_relationship_storage_key_derivation l\n        WHERE l.relationship_id=r.relationship_id) AS key_lineage_count,\n       (SELECT count(*) FROM model_relationship_reference_value_key_correspondence c\n        WHERE c.relationship_id=r.relationship_id) AS reference_value_key_correspondence_count,\n       (SELECT count(*) FROM model_relationship_storage_reference sr\n        WHERE sr.relationship_id=r.relationship_id) AS storage_reference_count\nFROM v_model_relationship_configuration_observations r;\n\nCREATE VIEW v_model_relationships AS\nSELECT r.*,\n       (SELECT count(*) FROM model_relationship_key_expression e\n        WHERE e.relationship_id=r.relationship_id) AS key_expression_count,\n       (SELECT count(*) FROM model_relationship_polymorphic_target p\n        WHERE p.relationship_id=r.relationship_id) AS polymorphic_target_count,\n       (SELECT count(*) FROM model_relationship_storage_key_derivation l\n        WHERE l.relationship_id=r.relationship_id) AS key_lineage_count,\n       (SELECT count(*) FROM model_relationship_reference_value_key_correspondence c\n        WHERE c.relationship_id=r.relationship_id) AS reference_value_key_correspondence_count,\n       (SELECT count(*) FROM model_relationship_storage_reference sr\n        WHERE sr.relationship_id=r.relationship_id) AS storage_reference_count\nFROM model_relationship_observation r;\n\nCREATE VIEW v_repository_summary AS\nWITH entity_counts AS (SELECT repo_id, count(*) AS entity_count FROM data_model_entity GROUP BY repo_id),\nattribute_counts AS (SELECT repo_id, count(*) AS attribute_count FROM data_model_attribute GROUP BY repo_id),\nstructure_counts AS (SELECT repo_id, count(*) AS persistent_structure_count FROM persistent_structure GROUP BY repo_id),\nstructure_attribute_counts AS (SELECT repo_id, count(*) AS persistent_structure_attribute_count FROM persistent_structure_attribute GROUP BY repo_id),\nasset_counts AS (SELECT repo_id, count(*) AS physical_asset_count FROM physical_asset GROUP BY repo_id),\nasset_fact_counts AS (SELECT repo_id, count(*) AS physical_asset_fact_count FROM physical_asset_fact GROUP BY repo_id),\ncolumn_counts AS (SELECT repo_id, count(*) AS physical_column_count FROM physical_column GROUP BY repo_id),\ndb_table_counts AS (SELECT repo_id, count(*) AS db_schema_table_count FROM db_schema_table GROUP BY repo_id),\ndb_column_counts AS (SELECT repo_id, count(*) AS db_schema_column_count FROM db_schema_column GROUP BY repo_id),\ndb_relationship_counts AS (SELECT repo_id, count(*) AS db_schema_relationship_count FROM db_schema_relationship GROUP BY repo_id),\nobserved_relationship_counts AS (SELECT repo_id, count(*) AS observed_table_relationship_count FROM table_relationship_observation GROUP BY repo_id),\nkey_observation_counts AS (SELECT repo_id, count(*) AS table_key_observation_count FROM table_key_observation GROUP BY repo_id),\nmodel_object_key_counts AS (SELECT repo_id, count(*) AS model_object_key_observation_count FROM model_object_key_observation GROUP BY repo_id),\nmodel_object_key_member_counts AS (SELECT repo_id, count(*) AS model_object_key_member_count FROM model_object_key_member GROUP BY repo_id),\nmodel_relationship_counts AS (SELECT source_repo_id AS repo_id, count(*) AS model_relationship_count FROM model_relationship_observation GROUP BY source_repo_id),\nmodel_embedded_counts AS (SELECT source_repo_id AS repo_id, count(*) AS model_embedded_field_count FROM model_embedded_field_observation GROUP BY source_repo_id),\nmodel_relationship_candidate_counts AS (SELECT source_repo_id AS repo_id, count(*) AS model_relationship_candidate_count FROM model_relationship_candidate GROUP BY source_repo_id),\nassociation_counts AS (SELECT repo_id, count(*) AS association_count FROM data_model_association GROUP BY repo_id),\njava_type_counts AS (SELECT repo_id, count(*) AS java_type_count FROM java_type_declaration GROUP BY repo_id),\ncode_field_counts AS (SELECT repo_id, count(*) AS code_field_count FROM code_field_observation GROUP BY repo_id),\ninheritance_counts AS (SELECT repo_id, count(*) AS inheritance_observation_count FROM java_inheritance_observation GROUP BY repo_id),\neffective_field_counts AS (SELECT repo_id, count(*) AS effective_field_count FROM effective_entity_field GROUP BY repo_id),\neffective_association_counts AS (SELECT repo_id, count(*) AS effective_association_count FROM effective_entity_association GROUP BY repo_id),\nsource_observation_counts AS (SELECT repo_id, count(*) AS source_observation_count FROM source_observation GROUP BY repo_id),\nannotation_counts AS (SELECT repo_id, count(*) AS code_annotation_count FROM source_observation WHERE fact_type='code_annotation' GROUP BY repo_id),\nconfiguration_counts AS (SELECT repo_id, count(*) AS configuration_entry_count FROM source_observation WHERE fact_type='configuration_entry' GROUP BY repo_id),\nmethod_call_counts AS (SELECT repo_id, count(*) AS java_method_call_count FROM source_observation WHERE fact_type='java_method_call_observation' GROUP BY repo_id),\nconstructed_value_counts AS (SELECT repo_id, count(*) AS constructed_value_count FROM source_observation WHERE fact_type='constructed_value_observation' GROUP BY repo_id),\ntype_reference_counts AS (SELECT repo_id, count(*) AS type_reference_count FROM source_observation WHERE fact_type='type_reference_observation' GROUP BY repo_id),\ntsa_observation_counts AS (SELECT repo_id, count(*) AS tsa_observation_count FROM source_observation WHERE fact_type LIKE 'tsa_%_observation' GROUP BY repo_id),\ngap_counts AS (SELECT repo_id, count(*) AS missing_fact_count FROM workspace_missing_fact GROUP BY repo_id)\nSELECT r.repo_id, r.system_name, r.project_code, r.analysis_profile,\n       coalesce(e.entity_count, 0) AS entity_count,\n       coalesce(a.attribute_count, 0) AS inline_attribute_count,\n       coalesce(s.persistent_structure_count, 0) AS persistent_structure_count,\n       coalesce(sa.persistent_structure_attribute_count, 0) AS persistent_structure_attribute_count,\n       coalesce(p.physical_asset_count, 0) AS physical_asset_count,\n       coalesce(f.physical_asset_fact_count, 0) AS physical_asset_fact_count,\n       coalesce(c.physical_column_count, 0) AS conceptual_model_physical_column_count,\n       coalesce(dt.db_schema_table_count, 0) AS db_schema_table_count,\n       coalesce(dc.db_schema_column_count, 0) AS db_schema_column_count,\n       coalesce(dr.db_schema_relationship_count, 0) AS db_schema_relationship_count,\n       coalesce(orr.observed_table_relationship_count, 0) AS observed_table_relationship_count,\n       coalesce(ko.table_key_observation_count, 0) AS table_key_observation_count,\n       coalesce(mok.model_object_key_observation_count, 0) AS model_object_key_observation_count,\n       coalesce(mokm.model_object_key_member_count, 0) AS model_object_key_member_count,\n       coalesce(mr.model_relationship_count, 0) AS model_relationship_count,\n       coalesce(me.model_embedded_field_count, 0) AS model_embedded_field_count,\n       coalesce(mrc.model_relationship_candidate_count, 0) AS model_relationship_candidate_count,\n       coalesce(x.association_count, 0) AS association_count,\n       coalesce(jt.java_type_count, 0) AS java_type_count,\n       coalesce(cfld.code_field_count, 0) AS code_field_count,\n       coalesce(ih.inheritance_observation_count, 0) AS inheritance_observation_count,\n       coalesce(ef.effective_field_count, 0) AS effective_field_count,\n       coalesce(ea.effective_association_count, 0) AS effective_association_count,\n       coalesce(so.source_observation_count, 0) AS source_observation_count,\n       coalesce(an.code_annotation_count, 0) AS code_annotation_count,\n       coalesce(cf.configuration_entry_count, 0) AS configuration_entry_count,\n       coalesce(mc.java_method_call_count, 0) AS java_method_call_count,\n       coalesce(cv.constructed_value_count, 0) AS constructed_value_count,\n       coalesce(tr.type_reference_count, 0) AS type_reference_count,\n       coalesce(tsa.tsa_observation_count, 0) AS tsa_observation_count,\n       coalesce(g.missing_fact_count, 0) AS missing_fact_count\nFROM workspace_repository r\nLEFT JOIN entity_counts e USING(repo_id)\nLEFT JOIN attribute_counts a USING(repo_id)\nLEFT JOIN structure_counts s USING(repo_id)\nLEFT JOIN structure_attribute_counts sa USING(repo_id)\nLEFT JOIN asset_counts p USING(repo_id)\nLEFT JOIN asset_fact_counts f USING(repo_id)\nLEFT JOIN column_counts c USING(repo_id)\nLEFT JOIN db_table_counts dt USING(repo_id)\nLEFT JOIN db_column_counts dc USING(repo_id)\nLEFT JOIN db_relationship_counts dr USING(repo_id)\nLEFT JOIN observed_relationship_counts orr USING(repo_id)\nLEFT JOIN key_observation_counts ko USING(repo_id)\nLEFT JOIN model_object_key_counts mok USING(repo_id)\nLEFT JOIN model_object_key_member_counts mokm USING(repo_id)\nLEFT JOIN model_relationship_counts mr USING(repo_id)\nLEFT JOIN model_embedded_counts me USING(repo_id)\nLEFT JOIN model_relationship_candidate_counts mrc USING(repo_id)\nLEFT JOIN association_counts x USING(repo_id)\nLEFT JOIN java_type_counts jt USING(repo_id)\nLEFT JOIN code_field_counts cfld USING(repo_id)\nLEFT JOIN inheritance_counts ih USING(repo_id)\nLEFT JOIN effective_field_counts ef USING(repo_id)\nLEFT JOIN effective_association_counts ea USING(repo_id)\nLEFT JOIN source_observation_counts so USING(repo_id)\nLEFT JOIN annotation_counts an USING(repo_id)\nLEFT JOIN configuration_counts cf USING(repo_id)\nLEFT JOIN method_call_counts mc USING(repo_id)\nLEFT JOIN constructed_value_counts cv USING(repo_id)\nLEFT JOIN type_reference_counts tr USING(repo_id)\nLEFT JOIN tsa_observation_counts tsa USING(repo_id)\nLEFT JOIN gap_counts g USING(repo_id);"

WORKSPACE_EXTENSION_VIEW_DDL += """

CREATE VIEW v_storage_records AS
SELECT c.*,
       json_extract_string(s.payload_json, '$.properties.api_framework') AS api_framework,
       json_extract_string(s.payload_json, '$.properties.observation_kind') AS storage_observation_kind,
       json_extract_string(s.payload_json, '$.properties.builder_receiver_expression') AS builder_receiver_expression,
       json_extract_string(s.payload_json, '$.properties.owner_fqcn') AS storage_owner_fqcn,
       json_extract_string(s.payload_json, '$.properties.owner_operation') AS storage_owner_operation,
       json_extract_string(s.payload_json, '$.properties.storage_alias') AS storage_alias,
       json_extract_string(s.payload_json, '$.properties.storage_key_field') AS storage_key_field,
       json_extract_string(s.payload_json, '$.properties.storage_key_expression') AS storage_key_expression,
       json_extract_string(s.payload_json, '$.properties.storage_key_local_variable') AS storage_key_local_variable,
       json_extract_string(s.payload_json, '$.properties.storage_key_source_observation_id') AS storage_key_source_observation_local_id,
       json_extract_string(s.payload_json, '$.properties.key_assignment_observation_id') AS key_assignment_observation_local_id,
       json_extract_string(s.payload_json, '$.properties.alias_assignment_observation_id') AS alias_assignment_observation_local_id,
       json_extract_string(s.payload_json, '$.properties.physical_reference_encoding') AS physical_reference_encoding,
       json_extract(s.payload_json, '$.properties.storage_key_input_symbols') AS storage_key_input_symbols_json,
       json_extract(s.payload_json, '$.properties.storage_key_expression_tree') AS storage_key_expression_tree_json
FROM v_source_observation_compact c
JOIN source_observation s USING(source_observation_occurrence_id)
WHERE c.fact_type='storage_record_observation';

CREATE VIEW v_storage_references AS
SELECT c.*,
       json_extract_string(s.payload_json, '$.properties.api_framework') AS api_framework,
       json_extract_string(s.payload_json, '$.properties.observation_kind') AS storage_observation_kind,
       json_extract_string(s.payload_json, '$.properties.source_owner_fqcn') AS source_owner_fqcn,
       json_extract_string(s.payload_json, '$.properties.source_operation') AS source_operation,
       json_extract_string(s.payload_json, '$.properties.source_alias') AS source_alias,
       json_extract_string(s.payload_json, '$.properties.source_field') AS source_field,
       json_extract_string(s.payload_json, '$.properties.source_field_expression') AS source_field_expression,
       json_extract_string(s.payload_json, '$.properties.reference_operation') AS reference_operation,
       json_extract_string(s.payload_json, '$.properties.reference_value_expression') AS reference_value_expression,
       json_extract_string(s.payload_json, '$.properties.reference_value_binding_resolution') AS reference_value_binding_resolution,
       json_extract_string(s.payload_json, '$.properties.target_converter_operation') AS target_converter_operation,
       json_extract_string(s.payload_json, '$.properties.target_storage_record_observation_id') AS target_storage_record_observation_local_id,
       json_extract_string(s.payload_json, '$.properties.target_alias') AS target_alias,
       json_extract_string(s.payload_json, '$.properties.target_storage_key_field') AS target_storage_key_field,
       json_extract_string(s.payload_json, '$.properties.target_storage_key_expression') AS target_storage_key_expression,
       json_extract_string(s.payload_json, '$.properties.target_storage_key_local_variable') AS target_storage_key_local_variable,
       json_extract_string(s.payload_json, '$.properties.value_origin') AS value_origin,
       json_extract_string(s.payload_json, '$.properties.type_source') AS type_source,
       json_extract_string(s.payload_json, '$.properties.key_source') AS key_source,
       json_extract_string(s.payload_json, '$.properties.physical_encoding') AS physical_encoding,
       json_extract(s.payload_json, '$.properties.target_storage_key_input_symbols') AS target_storage_key_input_symbols_json,
       json_extract(s.payload_json, '$.properties.target_storage_key_expression_tree') AS target_storage_key_expression_tree_json,
       json_extract(s.payload_json, '$.properties.binding_path') AS binding_path_json
FROM v_source_observation_compact c
JOIN source_observation s USING(source_observation_occurrence_id)
WHERE c.fact_type='storage_reference_observation';


CREATE VIEW v_model_relationship_storage_references AS
SELECT sr.*,
       src.source_path AS reference_source_path,
       src.line_start AS reference_line_start,
       src.line_end AS reference_line_end,
       target.source_path AS target_storage_record_source_path,
       target.line_start AS target_storage_record_line_start,
       target.line_end AS target_storage_record_line_end
FROM model_relationship_storage_reference sr
LEFT JOIN source_observation src
  ON src.source_observation_occurrence_id=sr.source_observation_occurrence_id
LEFT JOIN source_observation target
  ON target.source_observation_occurrence_id=sr.target_storage_record_observation_occurrence_id;

CREATE VIEW v_model_relationship_logical_identity_members AS
SELECT r.relationship_id,
       m.key_member_id,
       m.key_observation_id,
       m.repo_id,
       m.position,
       m.role_name,
       m.field_name,
       m.field_occurrence_id,
       m.field_owner_fqcn,
       m.field_resolution_kind,
       m.inheritance_depth,
       CASE
           WHEN lower(m.role_name) LIKE '%version%' THEN 'version'
           WHEN lower(m.role_name) LIKE '%collocation%' THEN 'collocation'
           ELSE 'identity'
       END AS logical_member_kind,
       m.candidate_field_occurrence_ids_json,
       m.argument_expression_json,
       m.payload_json
FROM model_relationship_observation r
JOIN model_object_key_member m
  ON list_contains(CAST(r.target_key_observation_ids_json AS VARCHAR[]), m.key_observation_id);

CREATE VIEW v_model_relationship_canonical_storage AS
SELECT r.relationship_id,
       r.source_repo_id,
       r.source_object_fqcn,
       r.source_field_name,
       r.target_repo_id,
       r.target_type_fqcn,
       r.relation_kind,
       r.cardinality,
       (SELECT count(*) FROM v_model_relationship_logical_identity_members i
        WHERE i.relationship_id=r.relationship_id AND i.logical_member_kind='identity') AS logical_identity_member_count,
       (SELECT count(*) FROM v_model_relationship_logical_identity_members i
        WHERE i.relationship_id=r.relationship_id AND i.logical_member_kind='version') AS version_member_count,
       (SELECT count(*) FROM v_model_relationship_logical_identity_members i
        WHERE i.relationship_id=r.relationship_id AND i.logical_member_kind='collocation') AS collocation_member_count,
       (SELECT count(*) FROM model_relationship_storage_reference sr
        WHERE sr.relationship_id=r.relationship_id) AS storage_reference_count
FROM model_relationship_observation r;
"""

